"""Structure of the minimal vectors of the distinct extreme forms found (recomputed from saved A_ext)."""
import json, glob, os, math
import numpy as np, voronoi as v
from math import gcd
here = os.path.dirname(os.path.abspath(__file__))

def index_of_span(S):
    """index in Z^n of the lattice generated by rows of S (integer row reduction), 0 if rank < n"""
    M = [list(map(int, r)) for r in S]
    n = len(M[0]); det = 1; row = 0
    for col in range(n):
        while True:
            nz = [i for i in range(row, len(M)) if M[i][col] != 0]
            if not nz: return 0
            p = min(nz, key=lambda i: abs(M[i][col]))
            M[row], M[p] = M[p], M[row]
            done = True
            for i in range(row + 1, len(M)):
                if M[i][col] != 0:
                    q = M[i][col] // M[row][col]
                    M[i] = [a - q * b for a, b in zip(M[i], M[row])]
                    if M[i][col] != 0: done = False
            if done: break
        det *= abs(M[row][col]); row += 1
    return det

out = []
for f in sorted(glob.glob(os.path.join(here, 'data', 'runs_n*_*.json'))):
    d = json.load(open(f)); n = d['n']
    if n < 4: continue
    seen = {}
    for r in d['recs']:
        key = (round(r['V_ext'], 5), r['pairs_ext'])
        seen.setdefault(key, [0, r]); seen[key][0] += 1
    for key, (cnt, r) in sorted(seen.items(), key=lambda kv: -kv[0][0]):
        A = np.array(r['A_ext']); A, U = v.lll_gram(A)
        S, vals, fl = v.short_vectors(A, 1 + 1e-7)
        q = r['denom_ext']
        ips = sorted(set(np.round(np.abs(q * (S @ A @ S.T)).ravel()).astype(int).tolist())) if q else None
        out.append(dict(n=n, mode=d['mode'], V=key[0], pairs=key[1], count=cnt, denom=q,
                        det_qA=(round(float(np.linalg.det(q * A)), 3) if q else None),
                        maxcoord=int(np.abs(S).max()), index_minvec_span=index_of_span(S),
                        abs_inner_products_times_q=ips, eut_min_coeff=r['eut_lp'],
                        V_over_n2=key[0] / n**2))
json.dump(out, open(os.path.join(here, 'data', 'structure.json'), 'w'), indent=1)
print('| mode | n | V | V/n^2 | pairs | count | q (qA integral, min q) | det(qA) | max coord of min vecs (LLL basis) | index of min-vector span | |q<x,y>| values | min eutaxy coeff |')
print('|---|---|---|---|---|---|---|---|---|---|---|---|')
for o in out:
    if o['n'] >= 8 and o['count'] < 2 and o['V'] < 0.85 * max(x['V'] for x in out if x['n'] == o['n']): continue
    print(f"| {o['mode']} | {o['n']} | {o['V']:.5f} | {o['V_over_n2']:.3f} | {o['pairs']} | {o['count']} | {o['denom']} | {o['det_qA']} | {o['maxcoord']} | {o['index_minvec_span']} | {o['abs_inner_products_times_q']} | {o['eut_min_coeff']:.4f} |")
